const inputs=[{padding:"16px",paddingInline:"8px"},{paddingInline:"8px",padding:"16px"}];
console.log(JSON.stringify({pin,sourceFiles:files,scope:"Unmodified function bodies, imports/export declarations removed for in-memory execution. Full CSS properties/lengths, identity normalization and transform, no responsive conditions or React/theme integration.",cases:inputs.map(input=>{const output=css(input);return {input,output,cssText:Object.entries(output).map(([k,v])=>k.replace(/[A-Z]/g,c=>"-"+c.toLowerCase())+":"+v).join(";")};})},null,2));
